#!/usr/bin/env node
/**
 * Ad-hoc probe for zurich-maps-3: drive the running wrangler dev server with
 * headless Chromium over CDP and report what specific interactions really do.
 * Not part of the repo; throwaway diagnostic.
 */
import { spawn } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const BASE_URL = (process.argv[2] || 'http://127.0.0.1:8787').replace(/\/$/, '');
const OUT = process.argv[3] || '/tmp/probe3-shots';
const PORT = 9333;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const CHROME = ['chromium', 'chromium-browser', 'google-chrome', 'google-chrome-stable'].find((bin) => {
  for (const dir of (process.env.PATH || '').split(':')) if (dir && existsSync(path.join(dir, bin))) return true;
  return false;
});

class Client {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); this.events = []; }
  static async connect(url) {
    const ws = new WebSocket(url);
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
    const c = new Client(ws);
    ws.onmessage = (m) => {
      const msg = JSON.parse(m.data);
      if (msg.id && c.pending.has(msg.id)) {
        const { resolve, reject } = c.pending.get(msg.id);
        c.pending.delete(msg.id);
        msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
      } else if (msg.method) c.events.push(msg);
    };
    return c;
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => { this.pending.set(id, { resolve, reject }); this.ws.send(JSON.stringify({ id, method, params })); });
  }
  async eval(expression) {
    const r = await this.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text);
    return r.result?.value;
  }
  async waitFor(expr, { timeout = 30000, label = expr } = {}) {
    const end = Date.now() + timeout;
    let last;
    while (Date.now() < end) {
      try { last = await this.eval(expr); if (last) return last; } catch (e) { last = e.message; }
      await sleep(250);
    }
    throw new Error(`timeout: ${label} (last ${JSON.stringify(last)})`);
  }
  async screenshot(file) {
    const { data } = await this.send('Page.captureScreenshot', { format: 'png' });
    await writeFile(file, Buffer.from(data, 'base64'));
    console.log(`  shot ${file}`);
  }
  async click(sel, { index = 0 } = {}) {
    const box = await this.eval(`(() => {
      const n = document.querySelectorAll(${JSON.stringify(sel)})[${index}];
      if (!n) return null;
      n.scrollIntoView({ block: 'center', behavior: 'instant', inline: 'nearest' });
      const r = n.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + r.height / 2, w: r.width, h: r.height, text: (n.textContent || '').trim().slice(0, 60) };
    })()`);
    if (!box) throw new Error(`no element ${sel}[${index}]`);
    const p = { x: Math.round(box.x), y: Math.round(box.y), button: 'left', clickCount: 1 };
    await this.send('Input.dispatchMouseEvent', { type: 'mouseMoved', ...p });
    await this.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...p });
    await this.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...p });
    return box;
  }
}

const userDataDir = path.join(os.tmpdir(), `probe3-chrome-${process.pid}`);
const chrome = spawn(CHROME, ['--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--hide-scrollbars', '--window-size=1440,960', `--remote-debugging-port=${PORT}`, `--user-data-dir=${userDataDir}`, 'about:blank'], { stdio: ['ignore', 'pipe', 'pipe'] });
const stderr = [];
chrome.stderr.on('data', (d) => stderr.push(String(d)));

let wsUrl = null;
for (let i = 0; i < 100 && !wsUrl; i++) {
  await sleep(300);
  try {
    const res = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' });
    if (res.ok) wsUrl = (await res.json()).webSocketDebuggerUrl;
  } catch { /* not up */ }
}
if (!wsUrl) { console.error('chrome did not start\n' + stderr.join('').slice(-500)); process.exit(2); }
await mkdir(OUT, { recursive: true });

const client = await Client.connect(wsUrl);
await client.send('Page.enable');
await client.send('Runtime.enable');
await client.send('Network.enable');
await client.send('Log.enable');

const consoleErrors = [];
const failedRequests = [];
client.ws.addEventListener('message', (m) => {
  const msg = JSON.parse(m.data);
  if (msg.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(msg.params.type)) {
    consoleErrors.push({ type: msg.params.type, text: msg.params.args.map((a) => a.value ?? a.description ?? a.type).join(' ').slice(0, 300) });
  }
  if (msg.method === 'Runtime.exceptionThrown') consoleErrors.push({ type: 'exception', text: (msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails.text || '').slice(0, 300) });
  if (msg.method === 'Network.loadingFailed') failedRequests.push({ url: msg.params.requestId, err: msg.params.errorText, blocked: msg.params.blockedReason });
});

const goto = async (url) => {
  await client.send('Page.navigate', { url });
  await sleep(500);
  await client.waitFor(`document.readyState === 'complete'`, { label: 'readyState' });
};

// ------------------------------------------------------------------ probe 1
console.log('\n== 1. world map: “Auf der Karte zeigen” ==');
await goto(`${BASE_URL}/?sel=e-rara:3946379`);
await client.waitFor(`document.querySelector('#detail-preview') && document.querySelector('#preview-meta')?.textContent?.includes('px')`, { timeout: 40000, label: 'world viewer loaded' });
const world = await client.eval(`(() => {
  const rec = document.querySelector('#detail-title')?.textContent;
  return { title: rec, meta: document.querySelector('#preview-meta')?.textContent, img: document.querySelector('#viewer-stage img')?.src?.slice(0, 120), readout: document.querySelector('#viewer-resolution')?.textContent };
})()`);
console.log('  viewer:', world);
await client.click(`#detail button[type=button]`, { index: 0 }).catch(() => {});
const fit = await client.eval(`(() => {
  const btns = [...document.querySelectorAll('#detail button')].map(b => b.textContent.trim());
  return btns;
})()`);
console.log('  detail buttons:', fit);
// click "Auf der Karte zeigen"
const clicked = await client.eval(`(() => {
  const b = [...document.querySelectorAll('#detail button')].find(x => x.textContent.trim().startsWith('Auf der Karte zeigen'));
  if (!b) return false; b.click(); return true;
})()`);
console.log('  clicked fit:', clicked);
await sleep(3000);
const mapState = await client.eval(`(() => {
  const url = location.search;
  const img = document.querySelector('#map-canvas, #map img, .app-map img');
  const status = document.querySelector('#map-status, #map-hint, [id*=map-status]')?.textContent?.trim().slice(0, 200);
  return { url, tiles: document.querySelectorAll('#map img').length, status, mapFirstSrc: document.querySelector('#map img')?.src?.slice(0, 140) };
})()`);
console.log('  after fit:', mapState);
await client.screenshot(`${OUT}/p1-world-fit.png`);

// ------------------------------------------------------------------ probe 2
console.log('\n== 2. cut-out (vv) across sheets of a 35-sheet work ==');
await goto(`${BASE_URL}/?sel=e-rara:8935807`);
await client.waitFor(`document.querySelector('#page-strip') && !document.querySelector('#page-strip').hidden`, { timeout: 60000, label: '35-sheet strip' });
const beforeSheet = await client.eval(`(() => ({ sh: new URLSearchParams(location.search).get('sh'), vv: new URLSearchParams(location.search).get('vv'), label: document.querySelector('#page-label')?.textContent }))()`);
console.log('  start:', beforeSheet);
// zoom into sheet 1 to create a region
for (let i = 0; i < 3; i++) { await client.click('#viewer-zoom-in'); await sleep(1200); }
await sleep(1500);
const zoomed = await client.eval(`(() => ({ vv: new URLSearchParams(location.search).get('vv'), readout: document.querySelector('#viewer-resolution')?.textContent, meta: document.querySelector('#preview-meta')?.textContent }))()`);
console.log('  zoomed on sheet 1:', zoomed);
// switch to sheet 5 via the strip
await client.eval(`(() => { const b = [...document.querySelectorAll('#page-strip button')].find(x => x.getAttribute('aria-label')?.includes('Blatt 5 ') || x.textContent.trim().startsWith('5')); if (b) b.click(); return !!b; })()`);
await sleep(3000);
const afterSwitch = await client.eval(`(() => ({ vv: new URLSearchParams(location.search).get('vv'), sh: new URLSearchParams(location.search).get('sh'), readout: document.querySelector('#viewer-resolution')?.textContent, meta: document.querySelector('#preview-meta')?.textContent, img: document.querySelector('#viewer-stage img')?.src?.slice(-90) }))()`);
console.log('  after switching to sheet 5:', afterSwitch);
await client.screenshot(`${OUT}/p2-sheet-switch.png`);

