/** Tiny CDP eval probe: node /tmp/cdp-eval.mjs <url> <seconds> '<expression>' */
import { spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const [url, waitSeconds, expression] = process.argv.slice(2);
const PORT = 9334;
