/**
 * A finite number for a numeric state key, or the documented default.
 *
 * `0` is a real value here: the equator is a real map view (the globe sheets of
 * the seed document an extent that is symmetric about it) and the Greenwich
 * meridian is longitude 0. The old `Number(value) || default` idiom treated both
 * as “missing”, so a shared `?lat=0.0000&lon=0.0000&z=2` link silently opened on
 * the Zürich default latitude instead, and the state the app wrote back had lost
 * the value. Only empty and unparseable values fall back.
 */
function numberOr(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback;
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

/** Keep numeric state inside sane bounds so a hand-written URL cannot break the UI. */
