  const out = { ...state };
  out.lat = Math.max(-85, Math.min(85, numberOr(out.lat, STATE_DEFAULTS.lat)));
  out.lon = normaliseLon(numberOr(out.lon, STATE_DEFAULTS.lon));
  out.zoom = Math.max(2, Math.min(18, numberOr(out.zoom, STATE_DEFAULTS.zoom)));

