/**
 * Documented coverage of every swisstopo layer this map draws.
 *
 * The WMTS capabilities document gives each base map and each comparison layer
 * the same WGS84BoundingBox (`5.140242 45.398181` – `11.47757 48.230651`, the
 * `SWITZERLAND` box below). Outside it the service answers
 * `400 {"error":{"code":400,"message":"Tile out of bounds …"}}` — measured with
 * curl 2026-10-19 for `ch.swisstopo.pixelkarte-farbe` (zoom 2 and zoom 12) and
 * for `ch.swisstopo.zeitreihen`. A browser reports each of those as a blocked
 * request (`net::ERR_BLOCKED_BY_ORB`) in the console. Since the world-wide seed
 * makes views outside Switzerland reachable (a globe sheet fitted with “Auf der
 * Karte zeigen”, a record in Cairo), those tiles are not requested at all.
 */
export const COVERAGE = SWITZERLAND;

/**
 * Does tile `x`/`y` at zoom `z` touch `box` (west/south/east/north)?
 *
 * `tileYToLat` counts southwards, so `y` is the tile's northern edge and
 * `y + 1` its southern edge. Pure, therefore unit-tested; the renderer uses it
 * to skip tiles the WMTS service cannot answer.
 */
export function tileTouchesCoverage(x, y, z, box = COVERAGE) {
  const west = tileXToLon(x, z);
  const east = tileXToLon(x + 1, z);
  const north = tileYToLat(y, z);
  const south = tileYToLat(y + 1, z);
  return east >= box.west && west <= box.east && south <= box.north && north >= box.south;
}

for (let y = y0; y <= y1; y += 1) {
