  /* --- 8r. the world beyond Switzerland: honest coverage, real equator --- */
  // Two verified defects of the global set (found in iteration 7-24):
  //  1. a view outside Switzerland made the map request a dozen swisstopo tiles
  //     the service can only answer with HTTP 400 (`Tile out of bounds …`), which
  //     the browser reports as blocked requests and logs as console errors — for
  //     a background that stays empty anyway;
  //  2. `?lat=0` was read as “no latitude”, so the state and the URL fell back to
  //     the Zürich default: “Auf der Karte zeigen” on a globe sheet produced a
  //     link that could not reproduce the fitted view.
  const failuresBeforeCoverage = failedRequests.length;
  await cdp.send('Page.navigate', { url: `${BASE_URL}/?lat=52.5200&lon=13.4050&z=12` });
  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length >= 0 && document.querySelector('#map') ? true : ''`, { label: 'Berlin view', timeout: 20_000 });
  await sleep(1200);
  const outsideCoverage = await cdp.eval(`(() => {
    const tiles = [...document.querySelectorAll('#map img')].filter((img) => /wmts\\.geo\\.admin\\.ch/.test(img.src));
    return {
      tiles: tiles.length,
      lat: new URLSearchParams(location.search).get('lat'),
      note: (document.querySelector('#map-visible-count')?.textContent || '').trim(),
      live: (document.querySelector('#map [role="status"]')?.textContent || '').trim(),
    };
  })()`);
  check(
    'outside the Grundkarte’s coverage the map requests no impossible tiles and says why',
    outsideCoverage.tiles === 0 && /deckt nur die Schweiz ab/.test(outsideCoverage.note) && failedRequests.length === failuresBeforeCoverage,
    `${JSON.stringify(outsideCoverage).slice(0, 260)} · new failed requests: ${failedRequests.length - failuresBeforeCoverage}`,
  );

  // The equator itself: the URL keeps the value after the app rewrote it, and a
  // real interaction (an eastward pan through the map's arrow keys) still reports
  // the equator — the old read-back wrote the Zürich default into the URL instead.
  await cdp.send('Page.navigate', { url: `${BASE_URL}/?lat=0.0000&lon=0.0000&z=2` });
  await cdp.waitFor(`document.querySelectorAll('#map img').length > 0`, { label: 'equator view', timeout: 20_000 });
  await sleep(500);
  const equatorBefore = await cdp.eval(`(() => ({
    lat: new URLSearchParams(location.search).get('lat'),
    tiles: [...document.querySelectorAll('#map img')].filter((img) => /wmts\\.geo\\.admin\\.ch/.test(img.src)).length,
    live: (document.querySelector('#map [role="status"]')?.textContent || '').trim(),
  }))()`);
  await cdp.eval(`document.querySelector('#map')?.focus(); true`);
  await cdp.pressKey('ArrowRight');
  await sleep(700);
  const equatorAfter = await cdp.eval(`(() => ({
    lat: new URLSearchParams(location.search).get('lat'),
    lon: new URLSearchParams(location.search).get('lon'),
    live: (document.querySelector('#map [role="status"]')?.textContent || '').trim(),
  }))()`);
  check(
